    pot += msg.value;

    uint random = uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty, msg.sender))) % 2;

    if (random == 0) {
        payable(bank).transfer(FEE_AMOUNT);
        payable(msg.sender).transfer(pot - FEE_AMOUNT);
    }
