// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    receive() external payable {}
    function setUp() public { c = new EtherLotto(); }
    function testFuzz_property(uint256 warpSeed, address actor) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));
        uint256 ts = 1000 + (warpSeed % 1_000_000);
        vm.warp(ts);
        vm.deal(actor, 1 ether);
        uint256 random = uint256(keccak256(abi.encodePacked(block.timestamp, block.difficulty, actor))) % 2;
        vm.assume(random == 0); // only admissible inputs are winning plays
        vm.prank(actor);
        c.play{value: 10}();
        assertTrue(c.pot() == 0);
    }
}
